import pandas as pd
import pytz
from datetime import datetime
from random import randint, seed as set_seed


def task_func(
    utc_datetime,
    cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney'],
    weather_conditions=['Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'],
    timezones={
        'New York': 'America/New_York',
        'London': 'Europe/London',
        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    set_seed(seed)

    utc_time = pd.Timestamp(utc_datetime)
    if utc_time.tzinfo is None:
        utc_time = utc_time.tz_localize('UTC')
    else:
        utc_time = utc_time.tz_convert('UTC')

    report = []
    for city in cities:
        timezone = pytz.timezone(timezones[city])
        local_time = utc_time.tz_convert(timezone)

        report.append({
            'City': city,
            'Local Time': local_time.strftime('%Y-%m-%d %H:%M:%S %Z'),
            'Weather Condition': weather_conditions[
                randint(0, len(weather_conditions) - 1)
            ]
        })

    return pd.DataFrame(report)

