        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    if (
        not isinstance(utc_datetime, datetime)
        or utc_datetime.tzinfo is None
        or utc_datetime.utcoffset() is None
        or utc_datetime.utcoffset().total_seconds() != 0
    ):
        raise ValueError(
            'utc_datetime must be a datetime object with tzinfo set to UTC.'
        )

    set_seed(seed)
    report = []

    for city in cities:
        timezone = pytz.timezone(timezones[city])
        local_time = utc_datetime.astimezone(timezone)

        report.append({
            'City': city,
            'Local Time': local_time.strftime('%Y-%m-%d %H:%M:%S %Z'),
            'Weather Condition': weather_conditions[
                randint(0, len(weather_conditions) - 1)
            ]
        })

    return pd.DataFrame(report)

